    " */\nconst CW = 12, CH = 24;\n\nconst tctx "
    "= ui.text.getContext(\"2d\", { alpha: fals"
    "e });\nconst pctx = ui.pix.getContext(\"2d"
    "\", { alpha: false });\n\n/* ---- the text "
    "screen ---------------------------------"
    "----------------- */\n\nfunction resizeTex"
    "t() {\n  ui.text.width = st.cols * CW;\n  "
    "ui.text.height = st.rows * CH;\n  st.cell"
    "s = new Uint16Array(st.cols * st.rows).f"
    "ill(0x0720);\n  tctx.textBaseline = \"top\""
    ";\n  tctx.font = `${CH - 4}px ui-monospac"
    "e, \"SF Mono\", Menlo, Consolas, monospace"
    "`;\n  paintText();\n}\n\nfunction paintCell("
    "x, y) {\n  const v = st.cells[y * st.cols"
    " + x];\n  const ch = v & 0xff, attr = v >"
    "> 8;\n  const px = x * CW, py = y * CH;\n\n"
    "  tctx.fillStyle = CGA[(attr >> 4) & 7];"
    "\n  tctx.fillRect(px, py, CW, CH);\n\n  con"
    "st caret = st.cur.on && st.cur.x === x &"
    "& st.cur.y === y;\n  if (caret) {\n    tct"
    "x.fillStyle = CGA[attr & 15];\n    tctx.f"
    "illRect(px, py + CH - 3, CW, 2);\n  }\n  i"
    "f (ch !== 32 && ch !== 0) {\n    tctx.fil"
    "lStyle = CGA[attr & 15];\n    tctx.fillTe"
    "xt(CP437[ch], px + 1, py + 2);\n  }\n}\n\nfu"
    "nction paintText() {\n  for (let y = 0; y"
    " < st.rows; y++) {\n    for (let x = 0; x"
    " < st.cols; x++) paintCell(x, y);\n  }\n}\n"
    "\n/* One repaint per animation frame howe"
    "ver many rows arrived, because a screen\n"
    " * clearing is twenty-five messages and "
    "twenty-five full repaints is a phone\n * "
    "that stutters on a `cls`. */\nfunction sc"
    "hedulePaint(rows) {\n  if (!st.pending) {"
    "\n    st.pending = true;\n    requestAnima"
    "tionFrame(() => { st.pending = false; fl"
    "ushRows(); });\n  }\n  for (const r of row"
    "s) st.dirtyRows.add(r);\n}\n\nfunction flus"
    "hRows() {\n  for (const y of st.dirtyRows"
    ") {\n    if (y >= st.rows) continue;\n    "
    "for (let x = 0; x < st.cols; x++) paintC"
    "ell(x, y);\n  }\n  st.dirtyRows.clear();\n}"
    "\n\n/*\n * The splash goes on the first thi"
    "ng that arrives, whatever it is - not in"
    "side\n * the mode switch below, which ret"
    "urns early when the mode has not changed"
    " and\n * so never ran at all for a board "
    "that started in text and stayed there.\n "
    "*/\nfunction showText() {\n  ui.splash.hid"
    "den = true;\n  if (st.mode === \"text\") re"
    "turn;\n  st.mode = \"text\";\n  ui.pix.hidde"
    "n = true;\n  ui.text.hidden = false;\n}\n\n/"
    "* ---- the picture ---------------------"
    "--------------------------------- */\n\nfu"
    "nction showPixels() {\n  ui.splash.hidden"
    " = true;\n  if (st.mode === \"pix\") return"
    ";\n  st.mode = \"pix\";\n  ui.text.hidden = "
    "true;\n  ui.pix.hidden = false;\n}\n\nfuncti"
    "on resizePix(w, h) {\n  if (ui.pix.width "
    "=== w && ui.pix.height === h) return;\n  "
    "ui.pix.width = w;\n  ui.pix.height = h;\n "
    " pctx.fillStyle = \"#000\";\n  pctx.fillRec"
    "t(0, 0, w, h);\n}\n\n/*\n * PackBits over 16"
    "-bit pixels, and over bytes.  Mirrors pa"
    "ck16 / pack8 in\n * apps/common/pixband/a"
    "g_pixband.c: a control byte, then either"
    " that many\n * literals or that many copi"
    "es of one.\n */\nfunction unpack16(v, at, "
    "end, out, n) {\n  let o = 0;\n  while (at "
    "< end) {\n    const ctl = v.getUint8(at++"
    ");\n    if (ctl & 0x80) {\n      const run"
    " = (ctl - 0x80) + 2;\n      const px = v."
    "getUint16(at, true); at += 2;\n      if ("
    "o + run > n) return false;\n      for (le"
    "t k = 0; k < run; k++) out[o++] = px;\n  "
    "  } else {\n      const lit = ctl + 1;\n  "
    "    if (o + lit > n) return false;\n     "
    " for (let k = 0; k < lit; k++) { out[o++"
    "] = v.getUint16(at, true); at += 2; }\n  "
    "  }\n  }\n  return o === n;\n}\n\nfunction un"
    "pack8(v, at, end, out, n) {\n  let o = 0;"
    "\n  while (at < end) {\n    const ctl = v."
    "getUint8(at++);\n    if (ctl & 0x80) {\n  "
    "    const run = (ctl - 0x80) + 2;\n      "
    "const b = v.getUint8(at++);\n      if (o "
    "+ run > n) return false;\n      for (let "
    "k = 0; k < run; k++) out[o++] = b;\n    }"
    " else {\n      const lit = ctl + 1;\n     "
    " if (o + lit > n) return false;\n      fo"
    "r (let k = 0; k < lit; k++) out[o++] = v"
    ".getUint8(at++);\n    }\n  }\n  return o =="
    "= n;\n}\n\nfunction band(op, v, at, end) {\n"
    "  const x = v.getUint16(at, true), y = v"
    ".getUint16(at + 2, true);\n  const w = v."
    "getUint16(at + 4, true), h = v.getUint16"
    "(at + 6, true);\n  at += 8;\n\n  const n = "
    "w * h;\n  if (n === 0 || n > 1 << 20) ret"
    "urn;\n  const px = new Uint16Array(n);\n\n "
    " if (op === OP_RAW) {\n    if (end - at !"
    "== n * 2) return;\n    for (let i = 0; i "
    "< n; i++) px[i] = v.getUint16(at + i * 2"
    ", true);\n  } else if (op === OP_PACK) {\n"
    "    if (!unpack16(v, at, end, px, n)) re"
    "turn;\n  } else {\n    const bpp = v.getUi"
    "nt8(at), ncol = v.getUint8(at + 1) + 1;\n"
    "    at += 2;\n    const pal = new Uint16A"
    "rray(ncol);\n    for (let i = 0; i < ncol"
    "; i++) { pal[i] = v.getUint16(at, true);"
    " at += 2; }\n    const bytes = bpp === 4 "
    "? ((n + 1) >> 1) : n;\n    const raw = ne"
    "w Uint8Array(bytes);\n    if (!unpack8(v,"
    " at, end, raw, bytes)) return;\n    for ("
    "let i = 0; i < n; i++) {\n      const idx"
    " = bpp === 4\n        ? ((i & 1) ? (raw[i"
    " >> 1] >> 4) : (raw[i >> 1] & 15))\n     "
    "   : raw[i];\n      if (idx >= ncol) retu"
    "rn;\n      px[i] = pal[idx];\n    }\n  }\n\n "
    " /* RGB565 to the canvas's RGBA, with th"
    "e low bits replicated into the high\n   *"
    " ones so that full white stays full whit"
    "e instead of landing at 248. */\n  const "
    "img = pctx.createImageData(w, h);\n  cons"
    "t d = img.data;\n  for (let i = 0, j = 0;"
    " i < n; i++) {\n    const c = px[i];\n    "
    "const r = (c >> 11) & 31, g = (c >> 5) &"
    " 63, b = c & 31;\n    d[j++] = (r << 3) |"
    " (r >> 2);\n    d[j++] = (g << 2) | (g >>"
    " 4);\n    d[j++] = (b << 3) | (b >> 2);\n "
    "   d[j++] = 255;\n  }\n  pctx.putImageData"
    "(img, x, y);\n  showPixels();\n}\n\n/* ---- "
    "the connection -------------------------"
    "-------------------------- */\n\n/*\n * The"
    " password is kept per board, so one phon"
    "e can hold several without being\n * aske"
    "d each time, and dropped the moment the "
    "board says it was wrong.  In the\n * brow"
    "ser's own storage: it never leaves this "
    "device, and what crosses the wire\n * is "
    "a digest of it and a nonce, never the pa"
    "ssword.\n */\nconst PW_KEY = \"argon.pw.\" +"
    " location.host;\n\nfunction storedPassword"
    "() {\n  try { return localStorage.getItem"
    "(PW_KEY) || \"\"; } catch (e) { return \"\";"
    " }\n}\n\nfunction rememberPassword(pw) {\n  "
    "try { if (pw) localStorage.setItem(PW_KE"
    "Y, pw); else localStorage.removeItem(PW_"
    "KEY); }\n  catch (e) { /* a private windo"
    "w; ask again next time */ }\n}\n\nfunction "
    "answerChallenge(nonce, pw) {\n  const byt"
    "es = new TextEncoder().encode(pw);\n  con"
    "st buf = new Uint8Array(nonce.length + b"
    "ytes.length);\n  buf.set(nonce, 0);\n  buf"
    ".set(bytes, nonce.length);\n  const diges"
    "t = sha1(buf);\n  const msg = new Uint8Ar"
    "ray(1 + digest.length);\n  msg[0] = IN_AU"
    "TH;\n  msg.set(digest, 1);\n  if (st.ws &&"
    " st.ws.readyState === 1) st.ws.send(msg)"
    ";\n}\n\nfunction askForPassword(nonce, wron"
    "g) {\n  ui.ask.classList.add(\"on\");\n  ui."
    "askwhy.textContent = wrong\n    ? \"That w"
    "as not it. Try again.\"\n    : \"Set in SYS"
    "TEM.CFG, section [phone].\";\n  ui.askwhy."
    "classList.toggle(\"bad\", !!wrong);\n  ui.a"
    "skpw.value = \"\";\n  setTimeout(() => ui.a"
    "skpw.focus(), 50);\n  /* The keys are nee"
    "ded now if they are ever needed: on a ph"
    "one whose own\n   * keyboard does not com"
    "e up, this dialogue is the first thing t"
    "hat has to be\n   * typed into, and a fol"
    "ded keyboard here is a dead end. */\n  if"
    " (window.matchMedia && window.matchMedia"
    "(\"(pointer: coarse)\").matches &&\n      !"
    "ui.kbd.classList.contains(\"on\")) {\n    u"
    "i.kbd.classList.add(\"on\");\n    ui.kb.cla"
    "ssList.add(\"held\");\n  }\n  st.pendingNonc"
    "e = nonce;\n}\n\nui.askform.addEventListene"
    "r(\"submit\", (e) => {\n  e.preventDefault("
    ");\n  const pw = ui.askpw.value;\n  if (!p"
    "w) return;\n  rememberPassword(pw);\n  ui."
    "ask.classList.remove(\"on\");\n  if (st.pen"
    "dingNonce) {\n    answerChallenge(st.pend"
    "ingNonce, pw);\n    st.pendingNonce = nul"
    "l;\n  } else {\n    connect();\n  }\n});\n\nfu"
    "nction connect() {\n  const url = (locati"
    "on.protocol === \"https:\" ? \"wss://\" : \"w"
    "s://\") +\n              location.host + \""
    "/ws\";\n  const ws = new WebSocket(url);\n "
    " ws.binaryType = \"arraybuffer\";\n  st.ws "
    "= ws;\n\n  ws.onopen = () => {\n    if (ws "
    "!== st.ws) { ws.close(); return; }\n    u"
    "i.dot.classList.add(\"on\");\n    ui.note.t"
    "extContent = location.host;\n    setBar(\""
    "\");\n    ws.send(new Uint8Array([IN_HELLO"
    "]));\n  };\n  ws.onclose = (ev) => {\n    /"
    "*\n     * Only from the socket that is cu"
    "rrent.  A page that opened two - and it\n"
    "     * could, see the visibility handler"
    " - gets the board's \"replaced\" for the\n "
    "    * one it abandoned, which is not new"
    "s and must not be shown as though the\n  "
    "   * live link had been taken away.  Cau"
    "ght exactly that way: a freshly loaded\n "
    "    * page saying another device had the"
    " screen while it was connected.\n     */\n"
    "    if (ws !== st.ws) return;\n    ui.dot"
    ".classList.remove(\"on\");\n\n    /*\n     * "
    "The board allows one client: there is on"
    "e screen and one keyboard.  When\n     * "
    "a second browser takes the link it says "
    "so in the close, and the one that\n     *"
    " lost it must NOT come straight back - t"
    "wo pages reconnecting at each\n     * oth"
    "er is a link that flaps about once a sec"
    "ond and looks like a fault.\n     * Wait "
    "to be asked instead, and say so where it"
    " can be read without\n     * covering the"
    " picture that is still on the glass.\n   "
    "  */\n    if (ev && ev.reason === \"replac"
    "ed\") {\n      ui.note.textContent = \"scre"
    "en taken\";\n      setBar(\"Another device "
    "has this screen \342\200\224 tap here to take it "
    "back\",\n             false, () => { setBa"
    "r(\"connecting\342\200\246\"); connect(); });\n     "
    " return;\n    }\n    if (ev && ev.reason ="
    "== \"badpass\") {\n      ui.note.textConten"
    "t = \"locked\";\n      rememberPassword(\"\")"
    ";\n      setBar(\"Wrong password \342\200\224 tap h"
    "ere to try again\", true, () => {\n       "
    " setBar(\"connecting\342\200\246\");\n        connec"
    "t();\n      });\n      askForPassword(null"
    ", true);\n      return;\n    }\n\n    ui.not"
    "e.textContent = \"reconnecting\342\200\246\";\n    s"
    "etBar(\"The board is not answering \342\200\224 re"
    "connecting\342\200\246\");\n    /*\n     * A second,"
    " not immediately.  A board that has just"
    " been reset refuses\n     * connections f"
    "or a few seconds, and a page that retrie"
    "s as fast as it can\n     * is a page tha"
    "t spends that time producing errors.\n   "
    "  */\n    setTimeout(connect, 1000);\n  };"
    "\n  ws.onerror = () => ws.close();\n  ws.o"
    "nmessage = (ev) => {\n    if (ws !== st.w"
    "s) return;\n    onMessage(new DataView(ev"
    ".data));\n  };\n}\n\nfunction onMessage(v) {"
    "\n  if (v.byteLength < 1) return;\n  const"
    " op = v.getUint8(0);\n\n  if (op === OP_AU"
    "TH) {\n    /* The board has asked who thi"
    "s is, and will send nothing else until i"
    "t is\n     * answered.  A password we alr"
    "eady hold goes straight back; otherwise "
    "the\n     * person is asked, once, and th"
    "e answer is kept for next time. */\n    c"
    "onst nonce = new Uint8Array(v.buffer, 1,"
    " v.byteLength - 1);\n    const pw = store"
    "dPassword();\n    if (pw) {\n      answerC"
    "hallenge(nonce, pw);\n    } else {\n      "
    "askForPassword(new Uint8Array(nonce), fa"
    "lse);\n    }\n    return;\n  }\n\n  /* Anythi"
    "ng else means the board is talking, so i"
    "t is satisfied. */\n  ui.ask.classList.re"
    "move(\"on\");\n\n  if (op === OP_INFO) {\n   "
    " st.surfW = v.getUint16(1, true);\n    st"
    ".surfH = v.getUint16(3, true);\n    const"
    " cols = v.getUint8(5), rows = v.getUint8"
    "(6);\n    st.cellW = v.getUint8(7) || 8;\n"
    "    st.cellH = v.getUint8(8) || 16;\n    "
    "if (cols && rows && (cols !== st.cols ||"
    " rows !== st.rows)) {\n      st.cols = co"
    "ls; st.rows = rows; resizeText();\n    }\n"
    "    if (st.surfW && st.surfH) resizePix("
    "st.surfW, st.surfH);\n    return;\n  }\n\n  "
    "if (op === OP_ROW) {\n    const y = v.get"
    "Uint8(1), n = v.getUint8(2);\n    if (y >"
    "= st.rows) return;\n    for (let x = 0; x"
    " < n && x < st.cols; x++) {\n      st.cel"
    "ls[y * st.cols + x] =\n        v.getUint8"
    "(3 + x * 2) | (v.getUint8(4 + x * 2) << "
    "8);\n    }\n    schedulePaint([y]);\n    sh"
    "owText();\n    return;\n  }\n\n  if (op === "
    "OP_CURSOR) {\n    const x = v.getUint8(1)"
    ", y = v.getUint8(2);\n    const ch = v.ge"
    "tUint8(3), attr = v.getUint8(4), on = v."
    "getUint8(5) !== 0;\n    const was = { x: "
    "st.cur.x, y: st.cur.y };\n    if (y < st."
    "rows && x < st.cols) st.cells[y * st.col"
    "s + x] = ch | (attr << 8);\n    st.cur = "
    "{ x, y, on };\n    schedulePaint([was.y, "
    "y]);\n    showText();\n    return;\n  }\n\n  "
    "if (op === OP_RAW || op === OP_PACK || o"
    "p === OP_IDX) {\n    band(op, v, 1, v.byt"
    "eLength);\n  }\n}\n\nfunction send(bytes) {\n"
    "  if (st.ws && st.ws.readyState === 1) s"
    "t.ws.send(new Uint8Array(bytes));\n}\n\n/* "
    "---- keys ------------------------------"
    "------------------------------- */\n\n/*\n "
    "* Every key from the page's own keyboard"
    " passes through here, and that is the\n *"
    " one place that knows where a key should"
    " go.\n *\n * Normally to the board.  While"
    " the password is being asked, into the f"
    "ield\n * instead - because the keys on th"
    "is page are the only keyboard some phone"
    "s\n * offer, and a password box you canno"
    "t type into is a board you cannot reach."
    "\n * Reported exactly that way, from both"
    " keyboards at once, which is what made i"
    "t\n * two bugs and not one: this was the "
    "half where the keys went to the machine\n"
    " * behind the dialogue.\n */\nfunction ask"
    "Open() { return ui.ask.classList.contain"
    "s(\"on\"); }\n\nfunction typeIntoAsk(hid, un"
    "icode) {\n  if (hid === K.back) {\n    ui."
    "askpw.value = ui.askpw.value.slice(0, -1"
    ");\n    return;\n  }\n  if (hid === K.enter"
    ") {\n    ui.askform.dispatchEvent(new Eve"
    "nt(\"submit\", {bubbles: true,\n           "
    "                                       c"
    "ancelable: true}));\n    return;\n  }\n  if"
    " (unicode >= 32) {\n    ui.askpw.value +="
    " String.fromCodePoint(unicode);\n  }\n}\n\nf"
    "unction sendKey(kind, hid, unicode, mods"
    ") {\n  if (askOpen()) {\n    if (kind === "
    "1) typeIntoAsk(hid, unicode);\n    return"
    ";\n  }\n  const m = (mods === undefined ? "
    "st.sticky : mods);\n  send([IN_KEY, kind,"
    " m, hid & 255, hid >> 8, unicode & 255,\n"
    "        (unicode >> 8) & 255, 0]);\n}\n\nfu"
    "nction tap(hid) {\n  sendKey(1, hid, 0);\n"
    "  sendKey(2, hid, 0);\n  clearSticky();\n}"
    "\n\nfunction clearSticky() {\n  if (!st.sti"
    "cky) return;\n  st.sticky = 0;\n  for (con"
    "st b of ui.keys.querySelectorAll(\"button"
    ".held\")) {\n    b.classList.remove(\"held\""
    ");\n  }\n}\n\n/*\n * The bar of keys a phone'"
    "s own keyboard does not have.\n *\n * Ctrl"
    " and Alt latch rather than repeat: there"
    " is no way to hold one down and\n * press"
    " a letter on a touch screen, so a tap ar"
    "ms it for the next keystroke and\n * the "
    "keystroke clears it.  That is how every "
    "terminal application on a phone\n * has t"
    "o do it, and it is the reason Ctrl+C fro"
    "m here reaches the shell at all.\n */\ncon"
    "st KEYBAR = [\n  [\"Esc\", () => tap(K.esc)"
    "],\n  [\"Tab\", () => tap(K.tab)],\n  [\"Ctrl"
    "\", \"mod\", MOD.ctrl],\n  [\"Alt\", \"mod\", MO"
    "D.alt],\n  [\"\342\206\221\", () => tap(K.up)],\n  [\""
    "\342\206\223\", () => tap(K.down)],\n  [\"\342\206\220\", () ="
    "> tap(K.left)],\n  [\"\342\206\222\", () => tap(K.ri"
    "ght)],\n  [\"\342\217\216\", () => tap(K.enter)],\n  "
    "[\"\342\214\253\", () => tap(K.back)],\n  [\"Home\", ("
    ") => tap(K.home)],\n  [\"End\", () => tap(K"
    ".end)],\n  [\"PgUp\", () => tap(K.pgup)],\n "
    " [\"PgDn\", () => tap(K.pgdn)],\n  [\"Del\", "
    "() => tap(K.del)],\n  [\"F1\", () => tap(K."
    "f1)], [\"F2\", () => tap(K.f2)], [\"F3\", ()"
    " => tap(K.f3)],\n  [\"F4\", () => tap(K.f4)"
    "], [\"F5\", () => tap(K.f5)], [\"F6\", () =>"
    " tap(K.f6)],\n  [\"F7\", () => tap(K.f7)], "
    "[\"F8\", () => tap(K.f8)], [\"F9\", () => ta"
    "p(K.f9)],\n  [\"F10\", () => tap(K.f10)], ["
    "\"F11\", () => tap(K.f11)], [\"F12\", () => "
    "tap(K.f12)],\n];\n\nfor (const item of KEYB"
    "AR) {\n  const b = document.createElement"
    "(\"button\");\n  b.textContent = item[0];\n "
    " if (item[1] === \"mod\") {\n    const bit "
    "= item[2];\n    b.onclick = () => {\n     "
    " st.sticky ^= bit;\n      b.classList.tog"
    "gle(\"held\", (st.sticky & bit) !== 0);\n  "
    "  };\n  } else {\n    b.onclick = item[1];"
    "\n  }\n  ui.keys.appendChild(b);\n}\n\n/* ---"
    "- the keyboard the page carries itself -"
    "----------------------------- */\n\n/*\n * "
    "Drawn here rather than asked of the phon"
    "e, because the phone says no.\n *\n * A br"
    "owser raises its keyboard for a field th"
    "e person can see and refuses it\n * for o"
    "ne parked off screen at zero opacity - a"
    "nd off screen is the only place\n * such "
    "a field can be parked behind a full-scre"
    "en canvas.  Reported as \"the\n * keyboard"
    " is not there, only the one row with Esc"
    " and Tab\", and it was exactly\n * that.  "
    "So these keys are the page's own, and wh"
    "ether they appear is not an\n * opinion a"
    "nything else gets to have.  `abc` in the"
    " header still tries the\n * phone's, for "
    "whoever wants their own autocomplete and"
    " emoji.\n *\n * Each key is [label, shifte"
    "d label, HID usage].  The HID goes out b"
    "eside the\n * character because this syst"
    "em's keycodes are USB usage ids and appl"
    "ications\n * read either - a shell wants "
    "the character, DOOM wants the key.\n */\nc"
    "onst KEYS = [\n  [[\"1\",\"!\",K[\"1\"]],[\"2\",\""
    "@\",K[\"2\"]],[\"3\",\"#\",K[\"3\"]],[\"4\",\"$\",K[\""
    "4\"]],\n   [\"5\",\"%\",K[\"5\"]],[\"6\",\"^\",K[\"6\""
    "]],[\"7\",\"&\",K[\"7\"]],[\"8\",\"*\",K[\"8\"]],\n  "
    " [\"9\",\"(\",K[\"9\"]],[\"0\",\")\",K[\"0\"]]],\n  ["
    "[\"q\",\"Q\",K.q],[\"w\",\"W\",K.w],[\"e\",\"E\",K.e"
    "],[\"r\",\"R\",K.r],[\"t\",\"T\",K.t],\n   [\"y\",\""
    "Y\",K.y],[\"u\",\"U\",K.u],[\"i\",\"I\",K.i],[\"o\""
    ",\"O\",K.o],[\"p\",\"P\",K.p]],\n  [[\"a\",\"A\",K."
    "a],[\"s\",\"S\",K.s],[\"d\",\"D\",K.d],[\"f\",\"F\","
    "K.f],[\"g\",\"G\",K.g],\n   [\"h\",\"H\",K.h],[\"j"
    "\",\"J\",K.j],[\"k\",\"K\",K.k],[\"l\",\"L\",K.l]],"
    "\n  [[\"z\",\"Z\",K.z],[\"x\",\"X\",K.x],[\"c\",\"C\""
    ",K.c],[\"v\",\"V\",K.v],[\"b\",\"B\",K.b],\n   [\""
    "n\",\"N\",K.n],[\"m\",\"M\",K.m],\n   [\",\",\"<\",K"
    ".comma],[\".\",\">\",K.period]],\n  [[\"\\\\\",\"|"
    "\",K.backslash],[\";\",\":\",K.semicolon],[\"-"
    "\",\"_\",K.minus],\n   [\"/\",\"?\",K.slash],[\"="
    "\",\"+\",K.equal],[\"'\",\"\\\"\",K.quote],\n   [\""
    "[\",\"{\",K.lbracket],[\"]\",\"}\",K.rbracket]]"
    ",\n];\n\nlet shifted = false;\n\nfunction key"
    "Button(spec) {\n  const b = document.crea"
    "teElement(\"button\");\n  const paint = () "
    "=> { b.textContent = shifted ? spec[1] :"
    " spec[0]; };\n  paint();\n  b._paint = pai"
    "nt;\n  b.addEventListener(\"pointerdown\", "
    "(e) => {\n    e.preventDefault();\n    con"
    "st ch = shifted ? spec[1] : spec[0];\n   "
    " const mods = st.sticky | (shifted ? MOD"
    ".shift : 0);\n    /*\n     * With Ctrl or "
    "Alt armed this is a chord and not a char"
    "acter: the shell\n     * wants Ctrl+C as "
    "a keystroke with a keycode, not as the l"
    "etter c.\n     */\n    const uni = (st.sti"
    "cky & (MOD.ctrl | MOD.alt)) ? 0 : ch.cod"
    "ePointAt(0);\n    sendKey(1, spec[2], uni"
    ", mods);\n    sendKey(2, spec[2], 0, mods"
    ");\n    clearSticky();\n    if (shifted) {"
    " shifted = false; repaintKeys(); }\n  });"
    "\n  return b;\n}\n\nfunction specialButton(l"
    "abel, cls, fn) {\n  const b = document.cr"
    "eateElement(\"button\");\n  b.textContent ="
    " label;\n  if (cls) b.className = cls;\n  "
    "b.addEventListener(\"pointerdown\", (e) =>"
    " { e.preventDefault(); fn(b); });\n  retu"
    "rn b;\n}\n\nfunction repaintKeys() {\n  for "
    "(const b of ui.kbd.querySelectorAll(\"but"
    "ton\")) {\n    if (b._paint) b._paint();\n "
    " }\n  const sh = ui.kbd.querySelector(\"bu"
    "tton.shift\");\n  if (sh) sh.classList.tog"
    "gle(\"held\", shifted);\n}\n\nfunction buildK"
    "eyboard() {\n  for (let i = 0; i < KEYS.l"
    "ength; i++) {\n    const row = document.c"
    "reateElement(\"div\");\n    row.className ="
    " \"row\";\n    if (i === 3) {\n      const s"
    "h = specialButton(\"\342\207\247\", \"mod shift\", ()"
    " => {\n        shifted = !shifted;\n      "
    "  repaintKeys();\n      });\n      sh.clas"
    "sList.add(\"shift\");\n      row.appendChil"
    "d(sh);\n    }\n    for (const spec of KEYS"
    "[i]) row.appendChild(keyButton(spec));\n "
    "   if (i === 2) {\n      row.appendChild("
    "specialButton(\"\342\214\253\", \"mod\", () => tap(K."
    "back)));\n    }\n    if (i === 3) {\n      "
    "row.appendChild(specialButton(\"\342\217\216\", \"mo"
    "d\", () => tap(K.enter)));\n    }\n    ui.k"
    "bd.appendChild(row);\n  }\n\n  const last ="
    " document.createElement(\"div\");\n  last.c"
    "lassName = \"row\";\n  last.appendChild(spe"
    "cialButton(\"Esc\", \"mod\", () => tap(K.esc"
    ")));\n  last.appendChild(specialButton(\"T"
    "ab\", \"mod\", () => tap(K.tab)));\n  /* Spa"
    "ce carries its character as well as its "
    "usage id.  The kernel maps a\n   * usage "
    "to a character for a real USB keyboard, "
    "so this would work either\n   * way - but"
    " a key that means a character and does n"
    "ot say so is a key that\n   * depends on "
    "somebody else's table staying right. */\n"
    "  last.appendChild(specialButton(\"space\""
    ", \"xwide\", () => {\n    sendKey(1, K.spac"
    "e, 32, st.sticky);\n    sendKey(2, K.spac"
    "e, 0, st.sticky);\n    clearSticky();\n  }"
    "));\n  last.appendChild(specialButton(\"`\""
    ", \"mod\", () => {\n    sendKey(1, K.grave,"
    " shifted ? 126 : 96, st.sticky);\n    sen"
    "dKey(2, K.grave, 0, st.sticky);\n    clea"
    "rSticky();\n  }));\n  last.appendChild(spe"
    "cialButton(\"\342\214\253\", \"mod\", () => tap(K.bac"
    "k)));\n  ui.kbd.appendChild(last);\n}\n\nbui"
    "ldKeyboard();\n\n/*\n * Up by default on an"
    "ything with a finger, folded away on a d"
    "esktop where a\n * real keyboard is alrea"
    "dy attached and these keys are only lost"
    " screen.  A\n * phone that opens this pag"
    "e and sees no keys has, from where its o"
    "wner is\n * standing, no keyboard at all "
    "- which is exactly how the first version"
    " was\n * reported.\n */\nif (window.matchMe"
    "dia && window.matchMedia(\"(pointer: coar"
    "se)\").matches) {\n  ui.kbd.classList.add("
    "\"on\");\n  ui.kb.classList.add(\"held\");\n}\n"
    "\nui.kb.onclick = () => {\n  ui.kbd.classL"
    "ist.toggle(\"on\");\n  ui.kb.classList.togg"
    "le(\"held\", ui.kbd.classList.contains(\"on"
    "\"));\n};\n\n/* The phone's own, for whoever"
    " wants it.  It may or may not appear - t"
    "hat is\n * the browser's decision and the"
    " reason the keys above exist. */\nui.nati"
    "ve.onclick = () => {\n  ui.sink.value = \""
    "\";\n  ui.sink.focus();\n};\n\n/*\n * A phone'"
    "s keyboard reports characters, not keys."
    "  Two paths, and both are\n * needed: `ke"
    "ydown` carries the named keys on anythin"
    "g with a real keyboard and\n * often noth"
    "ing useful on a touch one, while the hid"
    "den textarea's `input`\n * event carries "
    "what was actually composed - including a"
    "nything past ASCII,\n * which has no HID "
    "usage to be named by.\n */\nconst BY_CODE "
    "= {\n  Escape: K.esc, Tab: K.tab, Enter: "
    "K.enter, Backspace: K.back,\n  ArrowUp: K"
    ".up, ArrowDown: K.down, ArrowLeft: K.lef"
    "t, ArrowRight: K.right,\n  Home: K.home, "
    "End: K.end, PageUp: K.pgup, PageDown: K."
    "pgdn, Delete: K.del,\n  Space: K.space,\n}"
    ";\nfor (let i = 1; i <= 12; i++) BY_CODE["
    "\"F\" + i] = K[\"f\" + i];\n\nwindow.addEventL"
    "istener(\"keydown\", (e) => {\n  /*\n   * No"
    "t while the person is typing into a fiel"
    "d of this page's own.  This\n   * handler"
    " ends with preventDefault on anything it"
    " recognises, which for a\n   * text input"
    " means the character is never inserted -"
    " so the password box\n   * swallowed ever"
    "y key from a real keyboard and from a ph"
    "one's, and looked\n   * broken in exactly"
    " the way it was.\n   */\n  const t = e.tar"
    "get;\n  if (t && t !== ui.sink &&\n      ("
    "t.tagName === \"INPUT\" || t.tagName === \""
    "TEXTAREA\" ||\n       t.isContentEditable)"
    ") {\n    return;\n  }\n\n  let mods = 0;\n  i"
    "f (e.shiftKey) mods |= MOD.shift;\n  if ("
    "e.ctrlKey) mods |= MOD.ctrl;\n  if (e.alt"
    "Key) mods |= MOD.alt;\n  if (e.metaKey) m"
    "ods |= MOD.gui;\n  mods |= st.sticky;\n\n  "
    "let hid = BY_CODE[e.code] || 0;\n  if (!h"
    "id && /^Key[A-Z]$/.test(e.code)) hid = K"
    "[e.code[3].toLowerCase()];\n  if (!hid &&"
    " /^Digit[0-9]$/.test(e.code)) hid = K[e."
    "code[5]];\n\n  const uni = (e.key && e.key"
    ".length === 1) ? e.key.codePointAt(0) : "
    "0;\n  if (!hid && !uni) return;\n\n  e.prev"
    "entDefault();\n  sendKey(1, hid, (mods & "
    "MOD.ctrl) ? 0 : uni, mods);\n  sendKey(2,"
    " hid, 0, mods);\n  clearSticky();\n});\n\nui"
    ".sink.addEventListener(\"input\", () => {\n"
    "  const text = ui.sink.value;\n  ui.sink."
    "value = \"\";\n  if (!text) return;\n  if (a"
    "skOpen()) {\n    for (const ch of text) t"
    "ypeIntoAsk(0, ch.codePointAt(0));\n    re"
    "turn;\n  }\n  /*\n   * With Ctrl or Alt arm"
    "ed this is not text, it is a chord: the "
    "shell wants\n   * Ctrl+C as a keystroke w"
    "ith a keycode, not as the letter c.\n   *"
    "/\n  if (st.sticky && text.length === 1) "
    "{\n    const c = text.toLowerCase();\n    "
    "const hid = K[c] || 0;\n    if (hid) { ta"
    "p(hid); return; }\n  }\n  send([IN_TEXT, ."
    "..new TextEncoder().encode(text)]);\n  cl"
    "earSticky();\n});\n\nui.sink.addEventListen"
    "er(\"beforeinput\", (e) => {\n  if (e.input"
    "Type === \"deleteContentBackward\") { e.pr"
    "eventDefault(); tap(K.back); }\n  if (e.i"
    "nputType === \"insertLineBreak\") { e.prev"
    "entDefault(); tap(K.enter); }\n});\n\n/* --"
    "-- the pointer -------------------------"
    "----------------------------- */\n\n/*\n * "
    "Where a touch lands, in the pixels the b"
    "oard measures a pointer in.\n *\n * Two di"
    "fferent surfaces and the board says whic"
    "h is live: an application's,\n * whose si"
    "ze arrived with the picture, and the con"
    "sole's, which has no pixels\n * of its ow"
    "n and is measured in cells times the cel"
    "l size the kernel draws\n * with.  Gettin"
    "g this wrong is the bug that put the cur"
    "sor below the stylus on\n * the board's o"
    "wn touchscreen for a week, so it is comp"
    "uted from what the board\n * said rather "
    "than from what looks right.\n */\nfunction"
    " where(ev) {\n  const cv = (st.mode === \""
    "pix\") ? ui.pix : ui.text;\n  const r = cv"
    ".getBoundingClientRect();\n  if (r.width "
    "=== 0 || r.height === 0) return null;\n\n "
    " const fx = (ev.clientX - r.left) / r.wi"
    "dth;\n  const fy = (ev.clientY - r.top) /"
    " r.height;\n  if (fx < 0 || fx > 1 || fy "
    "< 0 || fy > 1) return null;\n\n  if (st.mo"
    "de === \"pix\") {\n    return [Math.floor(f"
    "x * st.surfW), Math.floor(fy * st.surfH)"
    "];\n  }\n  const col = Math.min(st.cols - "
    "1, Math.floor(fx * st.cols));\n  const ro"
    "w = Math.min(st.rows - 1, Math.floor(fy "
    "* st.rows));\n  return [col * st.cellW, r"
    "ow * st.cellH];\n}\n\nfunction sendPtr(kind"
    ", ev, buttons) {\n  const p = where(ev);\n"
    "  if (!p) return;\n  send([IN_PTR, kind, "
    "buttons, p[0] & 255, (p[0] >> 8) & 255,\n"
    "        p[1] & 255, (p[1] >> 8) & 255, 0"
    "]);\n}\n\nfor (const cv of [ui.text, ui.pix"
    "]) {\n  cv.addEventListener(\"pointerdown\""
    ", (e) => {\n    e.preventDefault();\n    c"
    "v.setPointerCapture(e.pointerId);\n    st"
    ".ptrDown = true;\n    sendPtr(1, e, 1);\n "
    " });\n  cv.addEventListener(\"pointermove\""
    ", (e) => {\n    if (!st.ptrDown) return;\n"
    "    e.preventDefault();\n    sendPtr(3, e"
    ", 1);\n  });\n  cv.addEventListener(\"point"
    "erup\", (e) => {\n    if (!st.ptrDown) ret"
    "urn;\n    e.preventDefault();\n    st.ptrD"
    "own = false;\n    sendPtr(2, e, 0);\n  });"
    "\n  cv.addEventListener(\"pointercancel\", "
    "() => { st.ptrDown = false; });\n  cv.add"
    "EventListener(\"contextmenu\", (e) => e.pr"
    "eventDefault());\n}\n\n/*\n * Coming back fr"
    "om a locked screen.  The socket is usual"
    "ly dead by then and the\n * browser has n"
    "ot noticed, so ask for everything: the b"
    "oard answers 'H' by\n * resending the geo"
    "metry and marking the whole screen as ow"
    "ed.\n */\ndocument.addEventListener(\"visib"
    "ilitychange\", () => {\n  if (document.vis"
    "ibilityState !== \"visible\") return;\n  /*"
    "\n   * CLOSING or CLOSED, not \"anything b"
    "ut OPEN\".  A socket still CONNECTING is\n"
    "   * one that has not failed yet, and op"
    "ening a second beside it makes the board"
    "\n   * - which allows one client - throw "
    "the first away and report it, which is a"
    "\n   * page telling its owner that somebo"
    "dy took the screen from them one second\n"
    "   * after they loaded it.\n   */\n  if (!"
    "st.ws || st.ws.readyState >= 2) { connec"
    "t(); return; }\n  if (st.ws.readyState =="
    "= 1) send([IN_HELLO]);\n});\n\nresizeText()"
    ";\nsetBar(\"connecting\342\200\246\");\nconnect();\n</"
    "script>\n";

#endif /* AG_PHONE_PAGE_H */
